package com.coraline.tycoon;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.phys.*;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
/** Disposable declared unlock/needs checkpoints; genuine item use, physical inspections and care. */
@Mod.EventBusSubscriber(modid="coraline",value=Dist.CLIENT)
public final class TycoonPhaseOneVisualCheck {
    private static final BlockPos HOUSE=new BlockPos(116000,180,116000),DOOR=HOUSE.offset(0,1,2);
    private static volatile int stage;private static int ticks,age;private static boolean started,clicked;private static UUID resident,residentEntity;private static BlockPos desk;private static int foodBefore,waterBefore;
    @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(!Boolean.getBoolean("coraline.tycoonPhaseOneCheck")||e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();mc.options.pauseOnLostFocus=false;if(mc.screen instanceof net.minecraft.client.gui.screens.PauseScreen)mc.setScreen(null);if(mc.player==null||mc.getSingleplayerServer()==null||mc.player.tickCount<80)return;mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);if(!started){started=true;mc.getSingleplayerServer().execute(()->setup(mc));return;}if(++ticks>10500)throw new IllegalStateException("Tycoon checkpoint timed out stage="+stage);age++;if(ticks%100==0)com.mojang.logging.LogUtils.getLogger().info("TYCOON_CLIENT stage={} age={} screen={} position={}",stage,age,mc.screen==null?"none":mc.screen.getClass().getSimpleName(),mc.player.position());
        if(stage==1){if(!clicked&&age>60&&mc.level.getBlockState(DOOR).is(TycoonContent.DOOR.get())){clicked=true;use(mc,DOOR);}if(age==85)shot(mc,"weaver_threads");mc.getSingleplayerServer().execute(()->{if(TycoonWorld.home(owner(mc)).active())next(2);});}
        else if(stage==2&&age>20){use(mc,DOOR);next(3);}
        else if(stage==3&&mc.level.dimension().equals(TycoonWorld.KEY)&&age>80){shot(mc,"white_void_platform");mc.getSingleplayerServer().execute(()->{var p=owner(mc);var h=TycoonWorld.home(p);p.teleportTo(p.serverLevel(),h.center().getX()-1.5,h.center().getY(),h.center().getZ()+2.5,180,12);p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,h.center().offset(1,0,-1).getCenter());});next(4);}
        else if(stage==4&&age>30){shot(mc,"platform_desk_and_return");use(mc,TycoonWorldPoint(mc,1,-1));next(5);}
        else if(stage==5){if(age==40){if(!(mc.screen instanceof com.coraline.client.TycoonScreen))throw new IllegalStateException("Real desk did not open management UI");shot(mc,"work_desk_ui");press(mc,"Upgrades");}if(age==50){shot(mc,"work_desk_upgrades");press(mc,"Progression");}if(age>60){shot(mc,"work_desk_progression");mc.getSingleplayerServer().execute(()->{var p=owner(mc);if(!TycoonShop.phone(p).startsWith("Orphanage Phone claimed"))throw new IllegalStateException("Phone claim failed");for(String id:List.of("orphan_bed","orphan_food_table","orphan_fridge","water_station","orphan_lamp","toy_box","storage_cabinet"))if(!TycoonShop.buy(p,id).startsWith("Purchased"))throw new IllegalStateException("Purchase failed "+id);TycoonWorld.leave(p);});mc.setScreen(null);next(6);}}
        else if(stage==6&&mc.level.dimension().equals(net.minecraft.world.level.Level.OVERWORLD)&&age>60){mc.getSingleplayerServer().execute(()->facilities(mc));next(7);}
        else if(stage==7){mc.getSingleplayerServer().execute(()->{if(stage!=7)return;var p=owner(mc);var h=TycoonWorld.home(p);if(age>100&&age%100==0)com.mojang.logging.LogUtils.getLogger().info("TYCOON_AGENCY_STAGE built={} inspect={} report={} node={}",h.state.getBoolean("AgencyBuilt"),h.state.getBoolean("InspectionRequested"),h.state.getString("InspectionReport"),h.state.getInt("InspectionNode"));if(h.state.getBoolean("AgencyBuilt")&&!h.state.getBoolean("InspectionRequested")&&!h.state.getBoolean("Approved")&&!h.state.contains("InspectionReport"))TycoonAgency.request(p);if(h.state.getBoolean("Approved")){var survey=TycoonRooms.survey(p);if(!survey.approved()||survey.capacity()!=1)throw new IllegalStateException("Physical facilities did not validate "+survey);var chosen=TycoonAgency.candidates(h).get(0);String result=TycoonAgency.place(p,chosen.id);if(!h.residents.containsKey(chosen.id))throw new IllegalStateException("Placement failed: "+result);resident=chosen.id;var r=h.residents.get(resident);r.need("Hunger",20);r.need("Thirst",80);r.need("Neglect",15);r.n.putLong("NextRequest",h.clock()+20000);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BREAD,3));next(8);}});}
        else if(stage==8){mc.getSingleplayerServer().execute(()->residentEntity=record(mc).n.getUUID("Entity"));var a=child(mc);if(a!=null&&age>100){shot(mc,"resident_arrival");mc.getSingleplayerServer().execute(()->frameChild(mc));next(9);}}
        else if(stage==9&&age>5){var a=child(mc);if(a!=null&&mc.player.distanceToSqr(a)<16&&mc.player.getMainHandItem().is(Items.BREAD)){mc.getSingleplayerServer().execute(()->{var p=owner(mc);var a2=p.server.overworld().getEntity(record(mc).n.getUUID("Entity"));com.mojang.logging.LogUtils.getLogger().info("TYCOON_MANUAL_INPUT hand={} distance={} hunger={}",p.getMainHandItem(),a2==null?-1:p.distanceToSqr(a2),record(mc).need("Hunger"));});mc.gameMode.interact(mc.player,a,InteractionHand.MAIN_HAND);next(10);}else if(age%20==0)mc.getSingleplayerServer().execute(()->frameChild(mc));}
        else if(stage==10&&age>40&&age%20==0){mc.getSingleplayerServer().execute(()->{if(stage!=10)return;var p=owner(mc);var r=record(mc);if(!r.n.getBoolean("PlayerServed"))return;if(r.need("Hunger")<50||p.getMainHandItem().getCount()!=2)throw new IllegalStateException("Completed feeding did not debit one real bread and restore needs");mc.execute(()->shot(mc,"manual_meal"));r.n.putInt("ActionRemaining",0);r.need("Hunger",20);r.n.putLong("MealRequest",TycoonWorld.home(p).clock()-2000);var be=fridge(p);foodBefore=be.getItem(0).getCount();next(11);});}
        else if(stage==11){mc.getSingleplayerServer().execute(()->{var p=owner(mc);var r=record(mc);if(r.n.getBoolean("SelfServed")){if(fridge(p).getItem(0).getCount()!=foodBefore-1)throw new IllegalStateException("Self-service failed real food decrement");r.n.putInt("ActionRemaining",0);r.need("Thirst",10);r.n.putLong("WaterRequest",TycoonWorld.home(p).clock()-2000);waterBefore=water(p).water;next(12);}});}
        else if(stage==12){mc.getSingleplayerServer().execute(()->{var p=owner(mc);var r=record(mc);if(r.need("Thirst")>45&&water(p).water==waterBefore-1){r.n.putInt("ActionRemaining",0);r.n.putString("Request","CATCH");r.n.putLong("RequestExpires",TycoonWorld.home(p).clock()+2400);frameChild(mc);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(TycoonContent.BALL.get()));String accepted=TycoonCare.respond(p,resident,"accept");if(!accepted.startsWith("Accepted"))throw new IllegalStateException(accepted);next(13);}});}
        else if(stage==13){if(age%30==0){for(int slot=0;slot<9;slot++)if(mc.player.getInventory().getItem(slot).is(TycoonContent.BALL.get())){mc.player.getInventory().selected=slot;mc.gameMode.useItem(mc.player,InteractionHand.MAIN_HAND);break;}}mc.getSingleplayerServer().execute(()->{var p=owner(mc);var r=record(mc);if(age%100==0)com.mojang.logging.LogUtils.getLogger().info("TYCOON_CATCH passes={} ball={} held={} request={}",r.n.getInt("Passes"),r.n.hasUUID("Ball"),r.n.contains("HeldBall"),r.n.getString("Request"));if(r.n.getString("Request").isEmpty()){if(r.n.getInt("LastCatchPasses")<3||r.n.getLong("LastCatchTicks")<200)throw new IllegalStateException("Catch expired or completed without three returns and ten seconds");r.need("Hunger",80);r.need("Thirst",80);r.n.putLong("NextRequest",TycoonWorld.home(p).clock()+30000);r.n.getCompound("Traits").putDouble("Mischief",1);r.n.putLong("NextIncident",0);next(14);}});}
        else if(stage==14){mc.getSingleplayerServer().execute(()->{var p=owner(mc);var r=record(mc);if(!r.n.getString("Incident").isEmpty()){frameChild(mc);String result=TycoonCare.respond(p,resident,"forgive");if(!r.n.getString("Incident").isEmpty())throw new IllegalStateException("Forgiveness didn't resolve designated incident: "+result);next(15);}});}
        else if(stage==15&&age>50){shot(mc,"orphanage_household");mc.getSingleplayerServer().execute(()->{var p=owner(mc);var h=TycoonWorld.home(p);var snapshot=TycoonData.get(p.server).save(new net.minecraft.nbt.CompoundTag());if(!snapshot.equals(TycoonData.load(snapshot).save(new net.minecraft.nbt.CompoundTag())))throw new IllegalStateException("Tycoon save round-trip changed state");if(h.cooldown()<=0||!record(mc).active())throw new IllegalStateException("Placement cooldown/resident identity lost");p.server.overworld().getDataStorage().save();next(16);});}
        else if(stage==16&&age>20){mc.getSingleplayerServer().execute(()->{var p=owner(mc);var agency=BlockPos.of(TycoonWorld.home(p).state.getLong("Agency"));p.teleportTo(p.server.overworld(),agency.getX()-3.5,agency.getY()+1,agency.getZ()+10.5,180,0);p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,agency.above(2).getCenter());});next(17);}
        else if(stage==17&&age>50){shot(mc,"agency_exterior");mc.getSingleplayerServer().execute(()->{var p=owner(mc);var agency=BlockPos.of(TycoonWorld.home(p).state.getLong("Agency"));p.teleportTo(p.server.overworld(),agency.getX()-3.5,agency.getY()+1,agency.getZ()+1.5,180,0);p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,agency.offset(-4,2,-3).getCenter());TycoonNetwork.open(p,"phone",null);});next(18);}
        else if(stage==18&&age==30){press(mc,"Placements");}
        else if(stage==18&&age>50){shot(mc,"placement_preview");mc.setScreen(null);next(19);}
        else if(stage==19&&age>15){shot(mc,"agency_reception");com.mojang.logging.LogUtils.getLogger().info("TYCOON_PHASE_ONE_NATIVE_COMPLETE: declared reward/needs checkpoints; actual activation threads, owner platform/return, real desk UI/purchases/phone, generated agency, physical inspection, paid placement with saved receipt, manual food, real-fridge self-service, finite drinking water, three-return catch lasting at least ten seconds, recoverable incident, saved-data round-trip; not an hour-long full progression or user-save test");mc.stop();}
    }
    private static void next(int value){stage=value;age=0;clicked=false;}
    private static ServerPlayer owner(Minecraft mc){return mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);}
    private static TycoonData.Resident record(Minecraft mc){return TycoonWorld.home(owner(mc)).residents.get(resident);}
    private static TycoonNpc child(Minecraft mc){if(mc.level==null)return null;for(var e:mc.level.entitiesForRendering())if(e instanceof TycoonNpc a&&!a.staff()&&residentEntity!=null&&residentEntity.equals(a.getUUID()))return a;return null;}
    private static BlockPos TycoonWorldPoint(Minecraft mc,int x,int z){return desk;}
    private static void use(Minecraft mc,BlockPos at){mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(at.getCenter(),Direction.NORTH,at,false));}
    private static void press(Minecraft mc,String label){if(mc.screen==null)throw new IllegalStateException("No management UI for "+label);var button=mc.screen.children().stream().filter(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals(label)).findFirst().orElseThrow(()->new IllegalStateException("Missing management tab "+label));((net.minecraft.client.gui.components.Button)button).onPress();}
    private static void shot(Minecraft mc,String name){try{var dir=java.nio.file.Path.of("artwork/tycoon_phase1_qa").toAbsolutePath();java.nio.file.Files.createDirectories(dir);try(var pixels=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){pixels.writeToFile(dir.resolve(name+".png"));}}catch(java.io.IOException bad){throw new IllegalStateException(bad);}}
    private static void frameChild(Minecraft mc){var p=owner(mc);var r=record(mc);var a=p.server.overworld().getEntity(r.n.getUUID("Entity"));residentEntity=r.n.getUUID("Entity");if(a==null)return;var at=TycoonWorld.landing(p.server.overworld(),a.blockPosition().south(2));if(at!=null)p.teleportTo(p.server.overworld(),at.getX()+.5,at.getY(),at.getZ()+.5,180,0);p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,a.getEyePosition());}
    private static TycoonBlockEntity fridge(ServerPlayer p){return (TycoonBlockEntity)p.server.overworld().getBlockEntity(HOUSE.offset(3,1,-2));}
    private static TycoonBlockEntity water(ServerPlayer p){return (TycoonBlockEntity)p.server.overworld().getBlockEntity(HOUSE.offset(3,1,1));}
    private static void put(ServerPlayer p,String id,BlockPos at){int slot=-1;for(int i=0;i<36;i++)if(p.getInventory().getItem(i).is(TycoonContent.ITEMS.get(id).get())){slot=i;break;}if(slot<0)throw new IllegalStateException("Purchased block missing "+id);var stack=p.getInventory().getItem(slot);if(slot!=p.getInventory().selected)p.getInventory().setItem(slot,p.getMainHandItem());p.setItemInHand(InteractionHand.MAIN_HAND,stack);var context=new net.minecraft.world.item.context.BlockPlaceContext(p,InteractionHand.MAIN_HAND,stack,new BlockHitResult(at.below().getCenter().add(0,.5,0),Direction.UP,at.below(),false));var result=((BlockItem)stack.getItem()).place(context);if(!result.consumesAction())throw new IllegalStateException("Real placement rejected "+id+" @ "+at);}
    private static void facilities(Minecraft mc){var p=owner(mc);put(p,"orphan_bed",HOUSE.offset(-3,1,-2));put(p,"orphan_food_table",HOUSE.offset(0,1,-2));put(p,"orphan_fridge",HOUSE.offset(3,1,-2));put(p,"water_station",HOUSE.offset(3,1,1));put(p,"orphan_lamp",HOUSE.offset(-2,1,1));put(p,"toy_box",HOUSE.offset(-3,1,2));put(p,"storage_cabinet",HOUSE.offset(3,1,3));fridge(p).setItem(0,new ItemStack(Items.BREAD,16));water(p).water=8;water(p).setChanged();var h=TycoonWorld.home(p);h.state.putLong("AgencySearchOrigin",HOUSE.asLong());TycoonAgency.contact(p);p.teleportTo(p.server.overworld(),HOUSE.getX()+.5,HOUSE.getY()+1,HOUSE.getZ()+4.5,180,0);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.EMERALD,16));}
    private static void setup(Minecraft mc){var p=owner(mc);var l=p.server.overworld();p.server.getPlayerList().op(p.getGameProfile());p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.serverLevel().setDayTime(6000);
        for(int x=-10;x<=10;x++)for(int z=-10;z<=10;z++){var at=HOUSE.offset(x,0,z);l.getChunkAt(at);l.setBlock(at,Blocks.OAK_PLANKS.defaultBlockState(),2);for(int y=1;y<=6;y++)l.setBlock(at.above(y),(y==5&&Math.abs(x)<=6&&Math.abs(z)<=6||y<5&&(Math.abs(x)==6||Math.abs(z)==6)&&Math.abs(x)<=6&&Math.abs(z)<=6)?Blocks.OAK_PLANKS.defaultBlockState():Blocks.AIR.defaultBlockState(),2);}
        for(int y=1;y<=2;y++)l.setBlock(HOUSE.offset(0,y,6),Blocks.AIR.defaultBlockState(),2);desk=TycoonWorld.home(p).center().offset(1,0,-1);
        var bed=HOUSE.offset(2,1,3);l.setBlock(bed,Blocks.BLUE_BED.defaultBlockState(),2);p.setRespawnPosition(l.dimension(),bed,0,false,false);p.teleportTo(l,DOOR.getX()+.5,DOOR.getY(),DOOR.getZ()+3,180,10);p.getInventory().clearContent();TycoonWorld.giveDoor(p,false);put(p,"special_dimension_little_door",DOOR);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(TycoonContent.WEAVER.get()));p.getInventory().setItem(5,new ItemStack(TycoonContent.VOID_POWER.get(),64));p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,DOOR.getCenter());
        for(int x=-11;x<=11;x++)for(int z=-10;z<=10;z++)for(int y=-2;y<=7;y++){var at=HOUSE.offset(64+x,y,z);l.getChunkAt(at);l.setBlock(at,(y==-1?Blocks.GRASS_BLOCK:y==-2?Blocks.DIRT:Blocks.AIR).defaultBlockState(),2);}next(1);
    }
}
